            peek.setAttribute("transform", `translate(${(2500 - 800 * (1 - Math.pow(1 - k, 3))).toFixed(1)} 1010) rotate(${(-8 * k).toFixed(1)})`);
            cold.setAttribute("opacity", (0.4 * k).toFixed(2));
            const s = A.shake(t, PUFFS.map((at) => ({ at, amp: 8 })).concat([{ at: OPEN, amp: 20 }]));
            C.camera(S, { x: s.x, y: s.y });
